"},{"path":"rules.py","text":"def _ledger(revision_priority, tax_base, refunds):
    def rounded(n, d, mode):
        return (n + d // 2) // d if mode == "half_up" else n // d

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for pos, event in enumerate(data["events"]):
            seq = event.get("sequence", 0)
            if seq > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            if revision_priority == "sequence_first":
                rank = (seq, event.get("revision", 0), pos)
            else:
                rank = (event.get("revision", 0), pos)
            if event_id not in chosen or rank > chosen[event_id][0]:
                chosen[event_id] = (rank, event)

        balances = dict(data.get("opening", {}))
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, data["rounding"])
            base = raw if tax_base == "original" else net
            tax = rounded(base * event.get("tax_bp", 0), 10000, data["rounding"])
            total = net + tax
            if refunds and event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _resolver(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    rows = {name: {row["version"]: row for row in versions}
            for name, versions in packages.items()}
    options = {}
    for name in packages:
        options[name] = [None] + [v for v in rows[name]
                                  if v not in blocked.get(name, [])
                                  and (name not in pins or pins[name] == v)]

    best = None
    assignment = {}

    def check():
        installed = {name for name, version in assignment.items() if version is not None}
        if any(name not in installed or not lo <= assignment[name] <= hi
               for name, (lo, hi) in roots.items()):
            return False
        edges = {name: [] for name in installed}
        reachable = set()
        pending = list(roots)
        while pending:
            name = pending.pop()
            if name in reachable:
                continue
            if name not in installed:
                return False
            reachable.add(name)
            row = rows[name][assignment[name]]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                if other not in installed or not dep["min"] <= assignment[other] <= dep["max"]:
                    return False
                edges[name].append(other)
                pending.append(other)
        if reachable != installed:
            return False
        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            if any(not visit(other) for other in edges[name]):
                return False
            state[name] = 2
            return True
        return all(visit(name) for name in installed)

    def search(i):
        nonlocal best
        if i == len(names):
            if check():
                vector = tuple(-1 if assignment[n] is None else assignment[n] for n in names)
                if best is None or vector > best[0]:
                    best = (vector, {n: assignment[n] for n in names if assignment[n] is not None})
            return
        name = names[i]
        for version in options[name]:
            assignment[name] = version
            search(i + 1)
        del assignment[name]

    search(0)
    return {"error": "unsatisfiable"} if best is None else {"versions": best[1]}


def _jobs(data):
    jobs = [job for job in data["jobs"] if job["id"] not in data.get("blocked", [])]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    if not mandatory.issubset({job["id"] for job in jobs}) or len(mandatory) > k:
        return {"error": "impossible"}
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    n = len(jobs)
    for mask in range(1 << n):
        if mask.bit_count() != k:
            continue
        selected = [jobs[i] for i in range(n) if mask >> i & 1]
        ids = [job["id"] for job in selected]
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in selected:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not lo <= counts.get(group, 0) <= hi
               for group, (lo, hi) in quotas.items()):
            continue
        valid = True
        for job in selected:
            overlap = sum(other["start"] <= job["start"] < other["end"] for other in selected)
            if overlap > 2:
                valid = False
                break
        if not valid:
            continue
        sorted_ids = sorted(ids)
        value = sum(job["value"] for job in selected)
        if (best_value is None or value > best_value or
                (value == best_value and sorted_ids > best_ids)):
            best_value, best_ids = value, sorted_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _routes(data):
    import heapq
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    start = data["source"]
    initial_mask = bit.get(start, 0)
    state = (start, initial_mask, data["coupons"])
    distances = {state: data["start"]}
    queue = [(data["start"], start, initial_mask, data["coupons"])]
    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        current = (node, mask, coupons)
        if distances.get(current) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], coupons)]
            if coupons:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                choices.append((duration, coupons - 1))
            for duration, left in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                nxt = (next_node, next_mask, left)
                if arrival < distances.get(nxt, float("inf")):
                    distances[nxt] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, left))
    return {"arrival": None}


